func mustFixture(t *testing.T, f fixture) []byte {
	t.Helper()
	raw, err := base64.StdEncoding.DecodeString(f.b64)
	if err != nil {
		t.Fatalf("%s: bad fixture base64: %v", f.tag, err)
	}
	return raw
}
